        public void SaveData(string departmentBase, int year, int kvartal, SanatoriyProfilaktoriyModel model)
        {
            if (model == null)
            {
                throw new ApplicationException("Empty model");
            }

            using (KasabaKIATEntities db = new KasabaKIATEntities())
            {
                var query = from list in db.tbbu_profil_lager
                            where list.YEAR_FIN == year &&
                            list.KVARTAL == kvartal &&
                            list.DEPARTMENT_BASE == departmentBase &&
                            list.REPORT_TYPE == (int)ReportType.SanatoriyProfilaktori
                            select list;

                if (query.Any())
                {
                    var res = query.First();

                    db.tbbu_profil_lager.Remove(res);
                }

                db.tbbu_profil_lager.Add(new tbbu_profil_lager() { YEAR_FIN = year, KVARTAL = kvartal, DEPARTMENT_BASE = departmentBase, REPORT_TYPE = (int)ReportType.SanatoriyProfilaktori, CODE = "T1R010C01", VALUE = model.T1R010C01 });
                db.tbbu_profil_lager.Add(new tbbu_profil_lager() { YEAR_FIN = year, KVARTAL = kvartal, DEPARTMENT_BASE = departmentBase, REPORT_TYPE = (int)ReportType.SanatoriyProfilaktori, CODE = "T1R010C02", VALUE = model.T1R010C02 });
